# slugkit

Turns a title into a URL slug.

```js
const { slugify } = require('slugkit');

slugify('Hello, World!');            // 'hello-world'
slugify('Crème brûlée recipes');     // 'creme-brulee-recipes'
slugify('A very long title', { maxLength: 10 }); // 'a-very'
```

Options:
- `maxLength` (default 80): the slug is cut at a word boundary so it's no longer than this.
- `separator` (default `-`).

## Development

```
npm install
npm test        # or: node --test
```

The property tests in `test/slug.property.test.js` use [fast-check](https://github.com/dubzzz/fast-check).
'use strict';

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function slugify(title, { maxLength = 80, separator = '-' } = {}) {
  const sep = escapeRegExp(separator);
  let slug = String(title)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // drop accents: é -> e
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, separator)
    .replace(new RegExp(`^${sep}|${sep}$`), '');

  if (slug.length > maxLength) {
    const cut = slug.slice(0, maxLength + 1);
    const lastSep = cut.lastIndexOf(separator);
    slug = lastSep > 0 ? cut.slice(0, lastSep) : slug.slice(0, maxLength);
  }
  return slug;
}

module.exports = { slugify };
'use strict';

const test = require('node:test');
const fc = require('fast-check');
const { slugify } = require('../src/slug');

const SLUG = /^([a-z0-9]+(-[a-z0-9]+)*)?$/;

test('every slug is lowercase words joined by single dashes', () => {
  fc.assert(fc.property(fc.string(), (title) => SLUG.test(slugify(title))));
});

test('slugify is idempotent', () => {
  fc.assert(fc.property(fc.string(), (title) => slugify(slugify(title)) === slugify(title)));
});

test('slugs never exceed maxLength', () => {
  fc.assert(
    fc.property(fc.string(), fc.integer({ min: 1, max: 40 }), (title, maxLength) =>
      slugify(title, { maxLength }).length <= maxLength,
    ),
  );
});
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { slugify } = require('../src/slug');

test('lowercases and joins words with dashes', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('drops punctuation at both ends', () => {
  assert.strictEqual(slugify('  Hello, World!  '), 'hello-world');
});

test('removes accents', () => {
  assert.strictEqual(slugify('Crème brûlée recipes'), 'creme-brulee-recipes');
});

test('cuts long slugs at a word boundary', () => {
  assert.strictEqual(slugify('A very long title', { maxLength: 10 }), 'a-very');
});

test('custom separator', () => {
  assert.strictEqual(slugify('Hello World', { separator: '_' }), 'hello_world');
});
